 protected LocalAudioStore localAudioStore(){return new LocalAudioStore(this);}
 private LocalAudioStore.Sort localSort(){try{return LocalAudioStore.Sort.valueOf(getSharedPreferences("own_audio_ui",0).getString("sort","NEWEST"));}catch(Exception e){return LocalAudioStore.Sort.NEWEST;}}
 private void pickLocalAudio(){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("audio/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).putExtra(Intent.EXTRA_LOCAL_ONLY,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(pick,OPEN_LOCAL_AUDIO);}catch(ActivityNotFoundException e){toast("Системный проводник недоступен");}}
 private void sortLocalAudio(){String[] titles={"Сначала новые","Сначала старые","По названию"};LocalAudioStore.Sort[] values=LocalAudioStore.Sort.values();new AlertDialog.Builder(this).setTitle("Сортировка · по дате добавления или названию").setSingleChoiceItems(titles,localSort().ordinal(),(dialog,which)->{getSharedPreferences("own_audio_ui",0).edit().putString("sort",values[which].name()).apply();dialog.dismiss();load(false);}).setNegativeButton("Отмена",null).show();}
 private void loadLocalAudio(){final int ticket=++generation;final LocalAudioStore.Sort sort=localSort();busy=true;showPlaylists=false;nextHref="";more.setVisibility(View.GONE);status.setText("Проверяем локальные файлы…");worker.execute(()->{try{LocalAudioStore.Scan result=localAudioStore().scan(sort,()->{if(ticket!=generation||Thread.currentThread().isInterrupted())throw new InterruptedIOException();});ui(()->{if(ticket!=generation||!page.equals("own"))return;for(String removed:result.removed){PlaybackService s=PlaybackService.instance;if(s!=null)s.forgetLocal(removed);}PlaybackNotice.localRemoved(this);visible.clear();for(LocalAudioStore.Entry entry:result.entries)visible.add(entry.track());adapter.notifyDataSetChanged();busy=false;if(refreshLayout!=null)refreshLayout.finish();status.setText("Файлов: "+visible.size()+" · "+(sort==LocalAudioStore.Sort.NEWEST?"сначала новые":sort==LocalAudioStore.Sort.OLDEST?"сначала старые":"по названию")+(result.unavailable>0?" · временно недоступно: "+result.unavailable:"")+(result.removed.isEmpty()?"":" · удалённых ссылок убрано: "+result.removed.size()));empty("Добавьте аудиофайлы с устройства.\nФайлы не копируются; место остановки сохраняется отдельно для каждого.");updatePlayback();});}catch(Exception e){ui(()->{if(ticket!=generation)return;busy=false;if(refreshLayout!=null)refreshLayout.finish();toast("Не удалось проверить локальные файлы. Повторите обновление.");});}});}
 private void importLocalAudio(Intent data){if(localMutating){toast("Дождитесь завершения работы с файлами");return;}LinkedHashSet<Uri> chosen=new LinkedHashSet<>();if(data.getData()!=null)chosen.add(data.getData());ClipData clip=data.getClipData();if(clip!=null)for(int i=0;i<clip.getItemCount();i++)if(clip.getItemAt(i).getUri()!=null)chosen.add(clip.getItemAt(i).getUri());if(chosen.isEmpty())return;localMutating=true;int flags=data.getFlags();toast("Добавляем ссылки на аудио…");worker.execute(()->{int added=0,failed=0;for(Uri uri:chosen){if(Thread.currentThread().isInterrupted())break;try{localAudioStore().add(uri,flags);added++;}catch(Exception e){failed++;}}final int count=added,errors=failed;runOnUiThread(()->{localMutating=false;if(isDestroyed()||isFinishing())return;if(page.equals("own"))load(false);toast("Добавлено/обновлено: "+count+(errors>0?" · не добавлено: "+errors+". Проверьте формат и постоянный доступ в системном проводнике.":" · без копирования файлов"));});});}
 private void localAudioMenu(Library.Track track){new AlertDialog.Builder(this).setTitle(track.title).setItems(new String[]{"Убрать только из приложения","Удалить вместе с файлом"},(dialog,which)->{boolean file=which==1;new AlertDialog.Builder(this).setTitle(file?"Удалить файл с устройства?":"Убрать из приложения?").setMessage(file?"Сам файл будет удалён, если проводник разрешает удаление. Ссылка и сохранённая позиция тоже будут убраны. Если файл сейчас играет, воспроизведение остановится.":"Сам файл останется на устройстве. Ссылка и сохранённая позиция будут удалены. Если файл сейчас играет, воспроизведение остановится.").setNegativeButton("Отмена",null).setPositiveButton(file?"Удалить файл":"Убрать",(d,w)->removeLocalAudio(track.uri,file)).show();}).show();}
 private void removeLocalAudio(String uri,boolean file){if(localMutating){toast("Дождитесь завершения работы с файлами");return;}localMutating=true;PlaybackService s=PlaybackService.instance;if(s!=null)s.forgetLocal(uri);worker.execute(()->{try{if(file)localAudioStore().deleteFile(uri);else localAudioStore().remove(uri);runOnUiThread(()->{localMutating=false;if(isDestroyed()||isFinishing())return;PlaybackNotice.localRemoved(this);if(page.equals("own"))load(false);updatePlayback();toast(file?"Файл и запись удалены":"Ссылка и позиция удалены. Файл остался на устройстве.");});}catch(Exception e){runOnUiThread(()->{localMutating=false;if(isDestroyed()||isFinishing())return;if(Build.VERSION.SDK_INT>=29&&e instanceof android.app.RecoverableSecurityException){pendingLocalDelete=uri;try{startIntentSenderForResult(((android.app.RecoverableSecurityException)e).getUserAction().getActionIntent().getIntentSender(),CONFIRM_LOCAL_DELETE,null,0,0,0);return;}catch(Exception ignored){pendingLocalDelete="";}}toast("Файл удалить не удалось. Ссылка и позиция оставлены. Можно убрать только из приложения.");});}});}
